/** Plugin Name: TEMP PS S1688 kliento paskyra */
add_action('init', function(){
  if((isset($_GET['ps_blp'])?$_GET['ps_blp']:'')!=='R') return;
  header('Content-Type: application/json; charset=utf-8');
  $o=array('v'=>'S1688','wp'=>current_time('mysql'));
  global $wpdb;
  try{
    $u=get_user_by('email','ptomas887@gmail.com');
    if($u){
      $o['vartotojas']=array('id'=>$u->ID,'login'=>$u->user_login,'registruotas'=>$u->user_registered,
        'roles'=>$u->roles);
      foreach($wpdb->get_results($wpdb->prepare("SELECT meta_key,LEFT(meta_value,60) v FROM {$wpdb->usermeta} WHERE user_id=%d AND (meta_key LIKE '%%import%%' OR meta_key LIKE '%%welcome%%' OR meta_key LIKE '%%session%%' OR meta_key LIKE '%%last%%' OR meta_key='_ps_importas')",$u->ID),ARRAY_A) as $r) $o['meta'][$r['meta_key']]=$r['v'];
      $o['activation_key']=$wpdb->get_var($wpdb->prepare("SELECT user_activation_key FROM {$wpdb->users} WHERE ID=%d",$u->ID));
      $o['turi_slaptazodi']=(bool)$wpdb->get_var($wpdb->prepare("SELECT LENGTH(user_pass) FROM {$wpdb->users} WHERE ID=%d",$u->ID));
    } else $o['vartotojas']='nerastas';
    // siandienos laiskai
    $d=WP_CONTENT_DIR.'/uploads/wc-logs';
    foreach(scandir($d) as $f){ if(strpos($f,'transactional-emails-2026-09-09')===0) $o['laiskai']=substr(file_get_contents($d.'/'.$f),-2000); }
    // kiek importuotu klientu apskritai
    $o['importuotu']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->usermeta} WHERE meta_key='_ps_importas'");
    // ar buvo slaptazodzio atstatymo uzklausu siandien
    $o['reset_key_turi']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->users} WHERE user_activation_key<>''");
    // welcome modal
    $o['welcome_modal']=get_option('petshop_welcome_modal_enabled');
    // uzsakymai
    $t=$wpdb->prefix.'wc_orders';
    $o['uzsakymai']=$wpdb->get_results("SELECT id,status,date_created_gmt,payment_method,total_amount FROM $t WHERE billing_email='ptomas887@gmail.com' ORDER BY id",ARRAY_A);
    $o['likutis_14951']=get_post_meta(14951,'_stock',true);
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
});

