/** Plugin Name: TEMP PS S1689 veiksmai */
add_action('init', function(){
  $f=isset($_GET['ps_blq'])?$_GET['ps_blq']:'';
  if($f!=='A'&&$f!=='B') return;
  header('Content-Type: application/json; charset=utf-8');
  $o=array('v'=>'S1689','faze'=>$f,'wp'=>current_time('mysql'));
  global $wpdb;
  try{
    if($f==='A'){
      // 1. WELCOME MODAL
      $o['modal_pries']=get_option('petshop_welcome_modal_enabled');
      update_option('petshop_welcome_modal_enabled','1',false);
      $o['modal_po']=get_option('petshop_welcome_modal_enabled');

      // 2. Slaptazodzio pranesimas administratoriui — nutildom
      $kodas = <<<'KODAS'
/**
 * Petshop Pastas Slaptazodzio pranesimas adminui v1.0 (wp_password_change_notification_email)
 *
 * WordPress branduolys kaskart, kai vartotojas pasikeicia slaptazodi,
 * issiuncia laiska admin_email adresu. Su 5 666 importuotais klientais,
 * kurie po vieno atsistatineja slaptazodzius, tai uzkimsta dezute.
 * Klientas savo laiska gauna kaip iprasta — nutildomas TIK pranesimas adminui.
 */
add_filter( 'wp_password_change_notification_email', function( $email, $user, $blogname ) {
	$email['to'] = '';
	return $email;
}, 10, 3 );
KODAS;
      $sl=$wpdb->prefix.'snippets';
      $pav='Petshop Pastas Slaptazodzio pranesimas adminui v1.0 (wp_password_change_notification_email)';
      $esamas=$wpdb->get_row($wpdb->prepare("SELECT id FROM $sl WHERE name=%s",$pav),ARRAY_A);
      if(class_exists('\Code_Snippets\Snippet')){
        $s=new \Code_Snippets\Snippet();
        if($esamas) $s->id=(int)$esamas['id'];
        $s->name=$pav; $s->code=$kodas; $s->scope='global'; $s->active=true; $s->priority=10;
        $s->desc='Nutildo WP pranesima adminui apie kliento slaptazodzio keitima. S1689.';
        $r=\Code_Snippets\save_snippet($s);
        $o['snippetas']=is_object($r)?$r->id:$r;
      } else $o['snippetas']='klasės nėra';

      // 3. Dubliuoti uzsakymai
      foreach(array(35874,35875) as $id){
        $ord=wc_get_order($id);
        if(!$ord){ $o['uzsakymai'][$id]='nerastas'; continue; }
        if($ord->get_status()!=='pending'){ $o['uzsakymai'][$id]='ne pending, praleista ('.$ord->get_status().')'; continue; }
        $ord->update_status('cancelled','Atšaukta rankiniu būdu: klientas tam pačiam krepšeliui sukūrė tris užsakymus (#35873 laukia pavedimo). Likutis grąžinamas. S1689.');
        $o['uzsakymai'][$id]='atšauktas';
      }
      $o['likutis_po']=get_post_meta(14951,'_stock',true);
    }
    if($f==='B'){
      $o['modal']=get_option('petshop_welcome_modal_enabled');
      $o['filtras_registruotas']=has_filter('wp_password_change_notification_email')?'taip':'ne';
      $t=$wpdb->prefix.'wc_orders';
      $o['uzsakymai']=$wpdb->get_results("SELECT id,status,total_amount FROM $t WHERE id IN (35873,35874,35875)",ARRAY_A);
      $o['likutis_14951']=get_post_meta(14951,'_stock',true);
      // ar modalo kodas patenka i puslapi
      $r=wp_remote_get(home_url('/'),array('timeout'=>40,'sslverify'=>false,'headers'=>array('User-Agent'=>'Mozilla/5.0 Chrome/152')));
      $b=is_wp_error($r)?'':wp_remote_retrieve_body($r);
      $o['titulinis']=array('kodas'=>wp_remote_retrieve_response_code($r),
        'welcome'=>substr_count($b,'welcome')+substr_count($b,'ps-welcome'),
        'sveiki'=>substr_count($b,'Sveiki'),
        'modal'=>substr_count($b,'modal'));
      // modalo failas
      foreach(scandir(WPMU_PLUGIN_DIR) as $x){ if(stripos($x,'welcome')!==false||stripos($x,'modal')!==false) $o['modalo_failas'][]=$x; }
      $o['snippetai_welcome']=$wpdb->get_results("SELECT id,name,active FROM {$wpdb->prefix}snippets WHERE name LIKE '%elcome%' OR code LIKE '%welcome_modal_enabled%'",ARRAY_A);
    }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
});

