/** Plugin Name: TEMP PS S1689 patikra */
add_action('init', function(){
  if((isset($_GET['ps_blr'])?$_GET['ps_blr']:'')!=='R') return;
  header('Content-Type: application/json; charset=utf-8');
  $o=array('v'=>'S1689R','wp'=>current_time('mysql'));
  global $wpdb;
  try{
    // 1. Likutis ir uzsakymu pastabos
    foreach(array(35874,35875) as $id){
      $n=array();
      foreach(wc_get_order_notes(array('order_id'=>$id,'limit'=>8)) as $x) $n[]=$x->date_created->date('H:i:s').' '.substr(strip_tags($x->content),0,140);
      $o['pastabos'][$id]=$n;
      $ord=wc_get_order($id);
      $o['restock_meta'][$id]=$wpdb->get_results($wpdb->prepare("SELECT meta_key,LEFT(meta_value,40) v FROM {$wpdb->prefix}wc_orders_meta WHERE order_id=%d AND (meta_key LIKE '%%stock%%' OR meta_key LIKE '%%reduce%%')",$id),ARRAY_A);
    }
    $o['likutis_14951']=get_post_meta(14951,'_stock',true);
    $o['own_14951']=get_post_meta(14951,'_own_stock_qty',true);
    $o['sandelis_14951']=get_post_meta(14951,'_ps_sandelis',true);
    $o['ivykiai_14951']=$wpdb->get_results("SELECT laikas,laukas,sena,nauja,pastaba FROM {$wpdb->prefix}ps_ivykiai WHERE product_id=14951 ORDER BY id DESC LIMIT 8",ARRAY_A);

    // 2. Kur gyvena welcome modalas
    $rasta=array();
    foreach(scandir(WPMU_PLUGIN_DIR) as $x){
      if(substr($x,-4)!=='.php') continue;
      $c=file_get_contents(WPMU_PLUGIN_DIR.'/'.$x);
      $n=substr_count($c,'welcome_modal')+substr_count($c,'ps_welcome_seen')+substr_count($c,'Sveiki sugrįžę');
      if($n) $rasta['mu/'.$x]=$n;
    }
    $o['mu_failai']=$rasta;
    $sn=$wpdb->get_results("SELECT id,name,active,LENGTH(code) l FROM {$wpdb->prefix}snippets WHERE code LIKE '%welcome_modal%' OR code LIKE '%ps_welcome_seen%' OR code LIKE '%sugrįžę%' OR name LIKE '%Sveiki%'",ARRAY_A);
    $o['snippetai']=$sn;
    // visi aktyvus snippetai su 'modal'
    $o['modal_snippetai']=$wpdb->get_results("SELECT id,name,active FROM {$wpdb->prefix}snippets WHERE (code LIKE '%modal%' OR name LIKE '%modal%') AND active=1 LIMIT 10",ARRAY_A);
    // ar option skaitomas kur nors
    $o['option_naudojimas']=$wpdb->get_results("SELECT id,name,active FROM {$wpdb->prefix}snippets WHERE code LIKE '%petshop_welcome_modal_enabled%'",ARRAY_A);
    // vartotoju meta
    $o['ps_welcome_seen_kiek']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->usermeta} WHERE meta_key='ps_welcome_seen'");
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
});
